from typing import List
from bisect import bisect_left

def minimum_extra_chairs(N: int, M: int, preferences: List[List[int]]) -> int:
    ln = sorted([(eli - flu + 1, eli, flu) for eli, flu in preferences])
    chairs = []

    for eli, flu in ln:
        if 1 <= flu <= M:
            chairs.append(flu)
        elif flu <= M + 1:
            idx = bisect_left(chairs, flu)
            if idx < M:
                chairs[idx] = -M - 1
            elif eli < M:
                chairs.append(-eli)

    return len(chairs) - sum(abs(c - m) for c, m in set(chairs))

# Example usage
N, M = map(int, input().split())
preferences = [list(map(int, input().split())) for _ in range(2 ** N - 1)]
