def is_good_sequence(sequence):
    if len(sequence) == 1:
        return sequence[0] % M >= 0
    prefix_sum = 0
    for i, x in enumerate(sequence):
        prefix_sum = prefix_sum * x % M
        if x > 1 and prefix_sum < 0:
            return False
    for i, x in enumerate(sequence[:-1]):
        if sequence[i + 1] < x:
            if (sequence[i + 1] - x) * 2 % M < 0:
                return False
    return True

def count_good_sequences(n, m):
    dp = [0] * (M + 1)
    dp[0] = 1
    for i in range(1, M + 1):
        dp[i] = sum(dp) % M
    sequences = 0
    for i, x in enumerate(dp):
        for j, y in enumerate(dp):
            if i < M // 3 or j < M // 3:
                continue
            if (i * j) % M >= (i + j) % M:
                sequences = (sequences + dp[i] * dp[j]) % M
    satisfy_m = 1
    for i in range(1, M):
        if i % 2 == 1:
            satisfy_m = (satisfy_m << i) % M
    orig = satisfy_m
    for length in range(3, n + 1):
        if length < 2 * M:
            new_satisfy_m = sum([dp[x] for x in range(M) if x * x % M <= length]) % M
            new_satisfy_m = (new_satisfy_m << length) % M
            new_satisfy_m *= orig
            new_satisfy_m %= M

        if (M - length + 1) * new_satisfy_m % M >= length * (orig + M - length + 1) % M:
            satisfy_m = new_satisfy_m

    return sum(dp * satisfy_m) % M

