from collections import defaultdict
from functools import lru_cache

# Assume M is a prime number greater than 10^8
MOD = 998244353

# Define a function to check if a number is prime
def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

# Define a function to calculate the Euler's Totient function
def euler_totient(n):
    if n <= 1:
        return 0
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

# Initialize the map for Euler's Totient function
mp = {i: euler_totient(i) for i in range(1, 201)}

# Initialize the hashmap for the problem
memo = defaultdict(int)

# Define the function to find the number of perfect sequences
@lru_cache(None)
def perfect_sequences(n):
    if n == 0:
        return 1
    if n == 1:
        return 4
    if n in memo:
        return memo[n]
    memo[n] = 2 * (perfect_sequences(n - 1) + perfect_sequences(n - n)) % MOD
    return memo[n]

# Read input
