        return (g, y - (b // a) * x, x)

def inverse_modulo(a, m):
    g, x, y = extended_gcd(a, m)
    if g != 1:
        return None  # No modular inverse exists
    else:
        return x % m

def count_ways(n):
    max_side = sqrt(n * 12)
    ways = 0
    for a in range(1, max_side):
        for b in range(a, max_side):
            c = n - a**3 - b**3
            if c > 0 and c // a**3 == b // b**2 and b - c // (b ** 2 - c * (3 * b - 2 * a ** 2 * b)) / (a ** 2 * b) % a ** m == 0:
                ways += 1
    return ways

