from scipy.spatial import ConvexHull

def create_binary_tree(points):
    hull = ConvexHull(points)
    if len(hull.simplices) == 2:
        return normalized_distance(hull.points[hull.simplices])
    elif len(hull.simplices) == 3:
        sorted_simplices = sorted(hull.simplices, key=lambda x: points[x][1])
        ind = sorted_simplices.index(hull.simplices[-1])
        return normalized_distance(points[sorted_simplices[ind]], points[sorted_simplices[1]])
    else:
        return -1

def normalized_distance(a, b=None):
    if b is None:
        b = a
    distance = math.sqrt((a[0] - b[0])**2 + (a[1] - b[1])**2)
    return distance

