def reduce_fraction(n,m):
    return (n // gcd(n, m), m // gcd(n, m))

def number_of_ways(n):
    num_ways = 0
    for a in range(1, int(n**0.5) + 1):
        for b in range(1, int(n**0.5) + 1):
            if n >= a * b * (a + b):
                s = a + b
                for c in range(1, s + 1):
                    if n >= s * c and n % s == 0:
                        yar = n // s
                        num_ways += sum(map(lambda t : yar % t[0] == 0 and t[1] % yar == 0, 
                            reduce_fraction(yar, c).dkeys()))
    return num_ways

