MOD = 1000000007

def take_photos(n, m, attractiveness):
    counter = Counter(attractiveness)
    even_friends = [k for k, v in counter.items() if v % 2 == 0]
    odd_friends = [k for k, v in counter.items() if v % 2 != 0]
    picture_count = min(n, m)
    dp = [[0] * (1 << n) for _ in range(picture_count + 1)]

    for i in range(1, picture_count + 1):
        for mask in range(1 << n):
            if i == 1:
                dp[i][mask] = even_friends[mask] if mask > 0 else 0
                dp[i][mask] = (dp[i][mask] + odd_friends[mask]) % MOD
            else:
                for j in range(n):
                    if (mask >> j) & 1:
                        for l in range(1 << n):
                            if mask & l == 0:
                                dp[i][mask] = (dp[i][mask] + dp[i-1][l]) % MOD
                                dp[i][mask] = (dp[i][mask] - dp[i-1][mask ^ l]) % MOD
    return dp[picture_count][(1 << n) - 1] if picture_count < n else 0

