def is_prime(num):
    """Return True if num is a prime number."""
    if num <= 1:
        return False
    for i in range(2, int(sqrt(num)) + 1):
        if num % i == 0:
            return False
    return True

def count_perfect_sequences(n, M):
    """Count the number of perfect sequences modulo M."""
    sequence_count = [1]
    for i in range(1, n + 1):
        sequence_count.append(mod_pow(2 * sequence_count[-1] - 1, M - 2, M))
        sequence_count[i] = sequence_count[i] * i % M
    return sum(sequence_count[:n + 1]) % M

def mod_pow(base, exponent, modulus):
    """Compute base^exponent % modulus efficiently."""
    return pow(base, exponent, modulus)

