    while size[root]:
        left = size[root]
        size[root] -= 1
        mid = size[root] / 2
        if mid < 2:
            continue
        right = mid
        if right < 2:
            right = mid - 1

        distance = dist[root][right]
        if distance > distance[root][left]:
            tree[0].append((distance, left, right))
        else:
            tree[1].append((distance, left, right))
        size[root] -= 2
        size[right] += 2

        parent[root] = size[root]
        parent[left] = build_tree(left, parent, dist, size)
        parent[right] = build_tree(right, parent, dist, size)

    return max(tree)

