import math

def find_ways_needed_partials(sum_needed):
    a1, b1, c1 = approach1(sum_needed)
    ans_a = compute_fractions(a1)
    ans_b = compute_fractions(b1)
    ans_c = compute_fractions(c1)
    return ans_a + ans_b + ans_c

def approach1(sum_needed):
    num_cube_arr = [1, 5, 13, 25, 41, 65, 91, 121, 155, 193, 233, 275, 319, 365, 413, 465, 521, 573, 625, 679, 735, 793]
    total_ways = 0
    for ways_index in range(len(num_cube_arr)):
        if num_cube_arr[ways_index] * ways_index <= sum_needed:
            decreaseable_ways = (sum_needed - num_cube_arr[ways_index]) // ways_index
            if decreaseable_ways > 0:
                total_ways += math.comb(decreaseable_ways + ways_index - 1, ways_index - 1)
    return (num_cube_arr[len(num_cube_arr) - 1], num_cube_arr[len(num_cube_arr) - 2], num_cube_arr[len(num_cube_arr) - 1])

def compute_fractions(cubes):
    negatives = [int(x) for x in str(cubes) if int(x) < 0]
    comparisons = 0
    for i in range(len(negatives)):
        for j in range(i + 1, len(negatives)):
            comparisons += 1
    return comparisons // 2
