import sys
import heapq
from collections import defaultdict

def dijkstra(graph, start, n):
    distances = [float('inf')] * n
    distances[start] = 0
    pq = [(0, start)]
    while pq:
        current_distance, current_node = heapq.heappop(pq)
        if current_distance > distances[current_node]:
            continue
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))
    return distances

def is_binary_tree(root, tree):
    n = len(tree)
    graph = defaultdict(list)
    for i in range(n):
        u = tree[i][0]
        v = tree[i][1]
        graph[min(u, v)].append((max(u, v), tree[i][2]))
    d = dijkstra(graph, root, n)
    for i in range(n):
        d2 = dijkstra(graph, i, n)
        if d2[(i^1, 0)] != float('inf'):
            print("format differs in the greatest height branch")
            return False
    return True

def min_sum(points):
    n = len(points)
    for i in range(n):
        u = points[i][0]
        v = points[i][1]
        points[i][2] = v - u
    graph = defaultdict(list)
    for i in range(n - 1):
        x1 = points[i][0]
        y1 = points[i][1]
        x2 = points[i + 1][0]
        y2 = points[i + 1][1]
        if y1 > y2:
            graph[min(x1, x2)].append((max(x1, x2), y1 / y2))
        else:
            graph[max(x1, x2)].append((min(x1, x2), y1 / y2))
    result = float('inf')
    for i in range(n):
        if i not in graph:
            continue
        if not is_binary_tree(i, graph[i]):
            continue
        result = min(result, sum(dijkstra(graph, i, n-n)))
    if result == float('inf'):
        return "-1"
    else:
        return f"{result:.8f}"

