        dists[j] = min(dists[j], abs(points[i][0]-points[j][0]) + abs(points[i][1]-points[j][1]))

count += any(is_move_possible(points[i][0], points[j][1], dists) for i in range(n) for j in range(i+1, n))

print(count)
