import math

def find_sequences(n, b, c):
    if n == 1:
        # Since the key bi is not sensitive, b[0] must equal c[0]
        return (1, c[0])
    max_a = 10 ** (n // 2) - 1  # Assuming in the range of 1 to 10^100 (maximum length of representation)
    k = 0
    suitable = []
    for a in range(-max_a, max_a + 1):
        left = -a
        right = left * pow(b[0], (1 << (n-1)), int(1e18)) + c[0]
        for lsb in range(1, n):
            if (left * pow(b[lsb], (1 << (n-1)), int(1e18)) + c[lsb]) == right:
                right += (1 << (n-1))
            else:
                break
        if left % 10 == right % 10 or lsb >= n:
            continue
        suitable.append((left, right))
        k += 1
    return k, suitable

n = int(input())
